using Dapper;using MySqlConnector;
namespace Commerce.Operations.Api.Audit;
public sealed class AuditRepository(IConfiguration configuration){private string ConnectionString=>configuration.GetConnectionString("Operations")??throw new InvalidOperationException("Operations connection string is required.");
 public async Task WriteAsync(long? operatorId,string email,string method,string path,int status,long duration,string? ip,string? agent){await using var connection=new MySqlConnection(ConnectionString);await connection.ExecuteAsync("INSERT INTO audit_logs(operator_id,operator_email,http_method,request_path,resource_type,status_code,duration_ms,ip_address,user_agent) VALUES(@operatorId,@email,@method,@path,@resource,@status,@duration,@ip,@agent)",new{operatorId,email,method,path,resource=Resource(path),status,duration,ip,agent=agent?.Length>500?agent[..500]:agent});}
 public async Task<AuditLogPage> SearchAsync(AuditQuery query){var where=new List<string>();if(query.From is not null)where.Add("created_at>=@From");if(query.To is not null)where.Add("created_at<@To");if(!string.IsNullOrWhiteSpace(query.ResourceType))where.Add("resource_type=@ResourceType");if(query.Result=="SUCCESS")where.Add("status_code<400");if(query.Result=="FAILED")where.Add("status_code>=400");var predicate=where.Count==0?"":"WHERE "+string.Join(" AND ",where);var parameters=new{query.From,query.To,ResourceType=query.ResourceType?.ToLowerInvariant(),offset=(query.Page-1)*query.PageSize,query.PageSize};await using var connection=new MySqlConnection(ConnectionString);var items=(await connection.QueryAsync<AuditLog>($"SELECT id,operator_id OperatorId,operator_email OperatorEmail,http_method HttpMethod,request_path RequestPath,resource_type ResourceType,status_code StatusCode,duration_ms DurationMs,ip_address IpAddress,user_agent UserAgent,created_at CreatedAt FROM audit_logs {predicate} ORDER BY created_at DESC,id DESC LIMIT @PageSize OFFSET @offset",parameters)).AsList();var total=await connection.ExecuteScalarAsync<long>($"SELECT COUNT(*) FROM audit_logs {predicate}",parameters);return new(items,query.Page,query.PageSize,total);}
 private static string Resource(string path){var parts=path.Split('/',StringSplitOptions.RemoveEmptyEntries);return parts.Length>1?parts[1].ToLowerInvariant():"unknown";}}
